from collections import deque
def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    bg=max(set(v for row in grid for v in row), key=lambda v:sum(row.count(v) for row in grid))
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=bg or (r,c) in seen: continue
            comp={(r,c)}; seen.add((r,c)); q=deque([(r,c)])
            while q:
                y,x=q.popleft()
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==bg and (yy,xx) not in seen:
                        seen.add((yy,xx)); comp.add((yy,xx)); q.append((yy,xx))
            comps.append(comp)
    if len(comps)>1:
        largest=max(comps,key=len)
        for comp in comps:
            if comp is not largest:
                for r,c in comp: out[r][c]=4
    return out
